  createGearForUser,
  deleteGearForUser,
  getGearForUser,
  getGearStatsForUser,
  getGearSummaryForUser,
  removeGearReservationForUser,
  reserveGearForTripForUser,
} from "@/lib/gear/service";
import { getTripByIdForUser } from "@/lib/trips/service";

function jsonResult(data: unknown): MCPToolResult {
  return {
    content: [{ type: "text" as const, text: JSON.stringify(data, null, 2) }],
  };
}

export function createGearToolHandlers(
  supabase: SupabaseClient,
  userId: string
): GearToolHandlers {
  async function createGear(
    args: ToolArgumentsByName["create_gear"]
  ): Promise<MCPToolResult> {
    const {
      name,
      brand,
      type,
      model,
      serial_number,
      purchase_date,
      purchase_price,
      condition = "good",
      notes = "",
