export async function getGearStatsForUser(
  supabase: SupabaseClient,
  userId: string,
  groupBy: keyof Gear
) {
  const gear = await getGearForUser(supabase, userId);
  const stats: Record<
    string,
    {
      count: number;
      total_value: number;
      gear: Array<{
        id: string;
        name: string;
        brand: string;
        type: string;
        condition: string;
      }>;
    }
  > = {};

  gear.forEach((item) => {
    const key = String(item[groupBy] || "unknown");
    if (!stats[key]) {
      stats[key] = { count: 0, total_value: 0, gear: [] };
    }
    stats[key].count++;
    stats[key].total_value += item.purchase_price || 0;
    stats[key].gear.push({
      id: item.id,
      name: item.name,
      brand: item.brand,
      type: item.type,
      condition: item.condition,
    });
  });

  return { gear, stats };
}

