export async function addFilmToTripForUser(
  supabase: SupabaseClient,
  userId: string,
  tripId: string,
  filmId: string,
  quantity: number
) {
  await ensureTripOwned(supabase, tripId, userId);

  // available_count nets out other trips' reservations and any roll currently
  // loaded in a camera, so a roll can never be double-booked.
  const { data: availability } = await selectFilmAvailabilityById(
    supabase,
    filmId,
    userId
  );

  if (!availability) {
    throw new Error("Film not found");
  }

  if ((availability.available_count ?? 0) < quantity) {
    throw new Error(
      `Not enough available stock. Available: ${availability.available_count ?? 0}, Requested: ${quantity}`
    );
  }

  const { data: existingReservation } = await selectTripFilmReservation(
    supabase,
    tripId,
    filmId
  );

  if (existingReservation) {
    const { error } = await updateTripFilmReservation(
      supabase,
      tripId,
      filmId,
      existingReservation.quantity + quantity
    );

    if (error) {
      throw error;
    }

    return;
  }

  const { error } = await insertTripFilmReservation(
    supabase,
    tripId,
    filmId,
    quantity
  );

  if (error) {
    throw error;
  }
}

export async function updateFilmQuantityInTripForUser(
  supabase: SupabaseClient,
  userId: string,
  tripId: string,
  filmId: string,
  quantity: number
) {
  if (quantity < 1) {
    throw new Error("Quantity must be at least 1");
  }

  await ensureTripOwned(supabase, tripId, userId);

  const { error } = await updateTripFilmReservation(
    supabase,
    tripId,
    filmId,
    quantity
  );

  if (error) {
    throw error;
  }
}

export async function removeFilmFromTripForUser(
