"""export const MCP_SERVER_VERSION = "1.1.0";

// Upper bound for one tool call end to end. A call that runs past it returns
// an MCP error instead of leaving the client waiting. Override with
// MCP_TOOL_TIMEOUT_MS.
export const TOOL_TIMEOUT_MS = Number(process.env.MCP_TOOL_TIMEOUT_MS) || 30_000;

function errorResult(message: string): MCPToolResult {
  return {
    content: [{ type: "text" as const, text: `Error: ${message}` }],
    isError: true,
  };
}

// Runs one tool with a wall-clock bound. Every failure path becomes an MCP
// error result, so the client always gets a response.
export async function runTool(
  handlers: ToolHandlersByName,
  name: string,
  args: unknown
): Promise<MCPToolResult> {
  const handler = handlers[name as ToolName] as
    | ((args: unknown) => Promise<MCPToolResult>)
    | undefined;

  if (!handler) {
    return errorResult(`Unknown tool: ${name}`);
  }

  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<MCPToolResult>((resolve) => {
    timer = setTimeout(
      () =>
        resolve(
          errorResult(
            `Tool "${name}" timed out after ${TOOL_TIMEOUT_MS}ms. ` +
              `The request was abandoned; check the database and retry.`
          )
        ),
      TOOL_TIMEOUT_MS
    );
  });

  try {
    return await Promise.race([handler(args || {}), timeout]);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const isAbort =
      error instanceof Error &&
      (error.name === "TimeoutError" || error.name === "AbortError");
    return errorResult(
      isAbort ? `Tool "${name}" failed: a database request timed out (${message})` : message
    );
  } finally {
    clearTimeout(timer);
  }
}

// Captured once at startup. `ping` compares against the file on disk so a
// client can tell when it is talking to a process older than the last build.
const startedAt = new Date().toISOString();
const entryFile = process.argv[1] || "";

function readEntryModifiedAt(): string | null {
  try {
    return fs.statSync(entryFile).mtime.toISOString();
  } catch {
    return null;
  }
}

function readBuildInfo(): { built_at?: string; git_commit?: string } | null {
  try {
    return JSON.parse(
      fs.readFileSync(path.join(path.dirname(entryFile), "build-info.json"), "utf8")
    );
  } catch {
    return null;
  }
}

const entryModifiedAtStartup = readEntryModifiedAt();

export async function ping(): Promise<MCPToolResult> {
  const entryModifiedNow = readEntryModifiedAt();
  const stale =
    entryModifiedAtStartup !== null &&
    entryModifiedNow !== null &&
    entryModifiedNow > entryModifiedAtStartup;

  return {
    content: [
      {
        type: "text" as const,
        text: JSON.stringify(
          {
            ok: true,
            server_version: MCP_SERVER_VERSION,
            build: readBuildInfo(),
            process: {
              started_at: startedAt,
              pid: process.pid,
              entry_file: entryFile || null,
              entry_file_modified_at: entryModifiedNow,
            },
            stale,
            hint: stale
              ? "The server file changed after this process started. Quit and reopen the MCP client (Claude Desktop: ⌘Q) to load the new build."
              : null,
            timeouts_ms: { tool: TOOL_TIMEOUT_MS },
          },
          null,
          2
        ),
      },
    ],
  };
}

